effect.shader:
mat2 gmRotate(float radiansValue){
float s = sin(radiansValue);
float c = cos(radiansValue);
return mat2(c, -s, s, c);
}
vec3 gmSoftLimit(vec3 value){
float limitValue = max(softLimit, 0.001);
return value / (vec3(1.0) + value / limitValue);
}
void main(){
vec2 uv = acScreenNorm;
vec4 source = texture2DCv(inputImg.texture, uv);
float timeValue = evolution;
if(autoAnimate) timeValue += acTime * speed;
vec2 center = vec2(0.5 + centerX * 0.5, 0.5 + centerY * 0.5);
vec2 position = uv - center;
position.x *= acScreenSize.x / max(acScreenSize.y, 1.0);
position = gmRotate(angle) * position;
position *= zoom;
float radius = max(length(position), 0.00075);
vec2 radialDirection = position / radius;
vec2 gridBase = gmRotate(angle) * (uv - center);
gridBase = gridBase * zoom + 0.5;
vec3 channels = vec3(0.0);
for(int i = 0; i < 3; i++){
float phase = timeValue + channelPhase * float(i + 1);
float pulse = (sin(phase) + pulseBias) * abs(sin(radius * radialFrequency - phase * phaseRate));
vec2 lensUv = gridBase + radialDirection * pulse * explosion;
vec2 cell = abs(fract(lensUv * max(gridDensity, 0.001)) - 0.5);
float cellDistance = pow(
pow(max(cell.x, 0.00001), cellRoundness) +
pow(max(cell.y, 0.00001), cellRoundness),
1.0 / max(cellRoundness, 0.001)
);
float channelValue = lightWidth / max(cellDistance, 0.00075);
if(i == 0) channels.r = channelValue;
else if(i == 1) channels.g = channelValue;
else channels.b = channelValue;
}
float falloff = pow(radius, radialFalloff);
vec3 pattern = channels / max(falloff, 0.015);
pattern *= intensity;
pattern = gmSoftLimit(max(pattern, vec3(0.0)));
if(colorMode == 1){
float luminance = dot(pattern, vec3(0.2126, 0.7152, 0.0722));
pattern = tintColor.rgb * luminance;
}else if(colorMode == 2){
float luminance = dot(pattern, vec3(0.2126, 0.7152, 0.0722));
pattern = vec3(luminance);
}
vec3 generated = backgroundColor.rgb + pattern;
generated = clamp(generated, 0.0, 1.0);
if(invert) generated = vec3(1.0) - generated;
vec3 effected = generated;
if(blendMode == 1){
effected = clamp(source.rgb + generated, 0.0, 1.0);
}else if(blendMode == 2){
effected = vec3(1.0) - (vec3(1.0) - source.rgb) * (vec3(1.0) - generated);
}
vec3 outputColor = mix(source.rgb, effected, mixAmount);
float outputAlpha = clipToLayer ? source.a : 1.0;
gl_FragColor = vec4(outputColor * outputAlpha, outputAlpha);
gl_FragColor *= texture2DCv(inputImg.texture, acScreenNorm).a;
}
